/**
 * @file Type of the ELK worker script imported `with { type: "text" }` (worker-source.ts): the
 * minified script ships without a declaration of its own.
 */
declare module "elkjs/lib/elk-worker.min.js" {
  /**
   * The text of the worker script.
   */
  const script: string;
  export default script;
}
